import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"RoboReward: General-Purpose Vision-Language Reward Models for Robotics","description":"","frontmatter":{"title":"RoboReward: General-Purpose Vision-Language Reward Models for Robotics","arxiv":"2601.00675","date":"2026-01-02","authors":"Tony Lee, Andrew Wagenmaker, Karl Pertsch, Percy Liang, Sergey Levine, Chelsea Finn","categories":"cs.RO","topics":"通用具身智能, 机器人奖励模型, 真实世界强化学习","outline":[2,2]},"headers":[],"relativePath":"papers/2601.00675.md","filePath":"papers/2601.00675.md","lastUpdated":null}'),e={name:"papers/2601.00675.md"};function l(r,s,i,m,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="roboreward-general-purpose-vision-language-reward-models-for-robotics" tabindex="-1">RoboReward: General-Purpose Vision-Language Reward Models for Robotics <a class="header-anchor" href="#roboreward-general-purpose-vision-language-reward-models-for-robotics" aria-label="Permalink to &quot;RoboReward: General-Purpose Vision-Language Reward Models for Robotics&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2601.00675" target="_blank" rel="noreferrer">2601.00675</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-01-02</td></tr><tr><td><strong>作者</strong></td><td>Tony Lee, Andrew Wagenmaker, Karl Pertsch, Percy Liang, Sergey Levine, Chelsea Finn</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>用&quot;反事实重标注 + 时序截断&quot;把成功偏重的 OXE 演示翻成 1–5 级进度标签的负例阶梯，建成 54,135 例数据集与人工核验的 RoboRewardBench，训出的 8B 奖励模型以 MAE 0.665 在 22 个 VLM 中排第一，并驱动真机 RL 把两个任务成功率从 5%/10% 抬到 50%/80%。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>用 RL 改进机器人策略的前提是有奖励。真实世界里这个前提通常靠两条路满足：人工逐条标注 rollout 是否成功，或者手写一个脆弱的目标函数（末端到目标点的距离、物体是否被抬起超过某个高度）。前者不可扩展，后者一换任务就要重写，而且极易被策略钻空子。论文在 Introduction 里把这条归为 RL 在真机上落地的主要障碍：算法侧（SERL、Policy-Agnostic RL、DSRL 一系）已经能在真机上做高效 RL，卡住的是奖励设计里那个人。</p><p>VLM 看起来是天然的自动奖励模型——它能看视频、能读指令、能判断&quot;这段视频里机器人是否完成了指令&quot;。论文的立论是：这条路已有大量工作在走，却没有一个覆盖多任务、多本体的真机基准去回答&quot;它什么时候可信&quot;。</p><p>论文在动手建数据之前先用仿真把两件事钉死，这一步决定了后面所有设计。在 Robomimic 上用 DSRL 微调一个预训练 diffusion policy，比较三种学出来的奖励：二值成功、连续进度、离散进度（5 档）。结果是两种进度奖励都接近 ground-truth 奖励的收敛速度，而<strong>学出来的二值奖励明显更差</strong>——学&quot;做到几分&quot;比学&quot;做没做成&quot;容易。作者据此把奖励形式定为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">5</span><span class="mclose">}</span></span></span></span> 的离散进度分，另一条理由是人类标注离散档比标注连续值一致性更高。第二件事是把奖励模型的离线准确率与下游 RL 成绩对上：取不同收敛阶段的多个奖励模型 checkpoint 各跑一遍 RL，得到相关系数 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.83</span></span></span></span>。这条相关性是全篇 benchmark 存在的合法性依据——它说明在离线数据上刷 MAE 不是刷榜，而是对下游有预测力的代理指标。</p><p>这件事重要，还因为奖励模型的误差会被 RL 直接放大：偏乐观的奖励把策略推向&quot;看起来像完成了&quot;的行为，偏悲观的奖励则直接抹掉学习信号。论文附录 B.3 给出的三个 Gemini Robotics-ER 1.5 误判案例（详见 §7）正是这两种误差的实例。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文把相关工作分成三块，每块的不足都写得很具体。</p><p><strong>学出来的机器人奖励函数</strong>。早期从人类视频（TCN、Concept2Robot）或机器人轨迹（VIP、LIV、RoboCLIP）学奖励；近期改用 VLM，或做偏好式打分（RL-VLM-F、VARP、ERL-VLM），或直接从单条视频导出稀疏/稠密奖励（Vision-language models as success detectors、Rank2Reward、Adapt2Reward）。作者的诊断是这些工作<strong>几乎都只针对单一机器人平台训一个奖励模型</strong>，谈不上通用；任务专用成功分类器（如 <a href="/notes/papers/2502.05450">ConRFT</a> 的二值分类器、<a href="/notes/papers/2503.24278">AutoEval</a> 的成功判别器）准确率能做高，但一换任务就要重来。与本文最接近的两个是：ReWiND 用&quot;倒放演示&quot;做奖励重标注，但完全不看演示内容，也没有在现代 VLM 与多样真机上评过；Robo-Dopamine 是同期工作，做高精度操作的 process reward，权重与数据当时未开源，本文明说留待未来评测。</p><p><strong>评测侧</strong>。OpenGVL 排行榜评 14 个 VLM 做时序价值估计，但只定义了 6 个任务，且<strong>只用成功演示</strong>，因此测不出模型区分成败的能力。非机器人领域的 RewardBench / RewardBench 2 / VLRewardBench / Multimodal RewardBench 测的是文本与图像域的奖励模型，本文的结论是 VLM 在机器人奖励上的表现<strong>远落后于</strong>它们在图文域的水平。价值引导类工作（<a href="/notes/papers/2410.13816">V-GPS</a>、<a href="/notes/papers/2506.17811">RoboMonkey</a>）做的是测试时选择，训练信号仍来自演示数据本身，同样绕不开负例缺口。</p><p><strong>数据侧的结构性缺口</strong>。OXE、DROID、BridgeData V2、RH20T、AgiBot World 这类大规模真机语料都是用专家策略或遥操作采的演示，<strong>压倒性地由成功轨迹构成</strong>。这对 behavior cloning 是好事，对必须区分细粒度进度与失败的奖励模型是致命的。负例是最贵、最少被采集的那一类数据，这是全文方法设计的直接动因。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>不用本文结论作前提，这条路可以一步步走出来。</p><p>第一步是承认奖励形式本身是个未定变量。RL 文献里回合级奖励可以是二值、连续、离散，但没人系统比过在机器人上哪种更好学。先在仿真里把这个问题解决掉，代价很小，收益是后面所有标注工作都有依据。</p><p>第二步是承认数据结构：可用的大规模真机语料（OXE）里几乎全是成功演示，因为采集流程本身就是遥操作。要训能打分的模型，光有正例不行。</p><p>第三步是问：能否<strong>不额外采集</strong>就造出负例？两个思路都不需要新的机器人时间。其一是反事实重标注——同一段成功视频，配上一条它并没有完成的指令。其二是时序截断——把成功视频剪到更早的终点，得到&quot;部分进展&quot;的样本。作者自己把这个操作类比成 hindsight experience replay 的反向操作：HER 把失败重标成成功以增加正例，这里做的是 &quot;inverse-HER&quot;，把成功重标成失败以增加负例。</p><p>第四步是承认合成标签会有噪声，于是把标注流水线设计成&quot;高成本离线教师&quot;：多阶段生成 + 严格 rubric + VLM 拒绝式验证，并明说它太慢、不可能塞进 RL 循环，只用来蒸馏出一个单次前向的开源奖励模型。测试集再加一层人工核验，保证即使训练标签有噪声，<strong>评测</strong>仍然可信。</p><p>第五步是把它接回下游：奖励模型的价值只能由它驱动的策略改进来验证，所以把 8B 模型放进真机 RL，与一个专门为具身推理训练的强 VLM（Gemini Robotics-ER 1.5）以及人工奖励的上界作比较。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>大规模真机数据只教会模型&quot;成功长什么样&quot;，而奖励模型必须知道&quot;差多少&quot;。既然失败数据采不到，就从成功数据里<strong>构造</strong>它：换掉指令让视频与语言不匹配，剪掉后半段让任务停在半途。两种构造都不生成任何新像素，成本只有 LLM 调用，却能造出一条从&quot;完全不对&quot;到&quot;差一点&quot;的单调阶梯。再加上一个先在仿真里验证过的选择——打 1–5 级进度分而不是二值成功——一个 4B–8B 的视觉-语言模型就能在短时程机器人任务上打分打得比大得多的通用 VLM 更准。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>用论文自己举的例子走一遍：一段 OXE 视频，机器人把一个辣椒放进灶台上的锅里，原始指令 place the pepper in the pot，原始标签 5 分。</p><ol><li><strong>数据来源</strong>。OXE 约 100 万条真机演示、22 种本体，但单个子数据集内部高度重复（往往同一场景同一摆位），因此每个子数据集<strong>均匀下采样至多 1200 条</strong>。OXE 全是演示，一律赋分 5。<a href="/notes/papers/2506.18123">RoboArena</a> 是 DROID 平台上的分布式真机策略评测数据，天然含成功与失败混合的 rollout，人类评测员给的 0–100 进度分被映射到 1–5，不做下采样。</li><li><strong>指令清洗</strong>。用 Qwen3-4B-Instruct-2507 做纯文本改写，只修拼写与语法（&quot;palce dishes in the dish rack&quot; → &quot;place the dishes in the dish rack&quot;），显式要求语义不变。</li><li><strong>反事实重标注</strong>（四阶段）。(a) 用 <strong>gpt-5-mini-2025-08-07</strong> 对以 1 FPS 抽帧的视频做详细描述，强制它按&quot;机器人基座视角&quot;判定左右、重点描述末帧；(b) 同一模型做 planning，设计四种<strong>互不相同</strong>的失败模式，并要求满足严格序 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6835em;vertical-align:-0.0391em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6835em;vertical-align:-0.0391em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6835em;vertical-align:-0.0391em;"></span><span class="mord">3</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6835em;vertical-align:-0.0391em;"></span><span class="mord">4</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span>；(c) Qwen3-4B 按分数逐条生成祈使句指令，限制 25 词以内、只能引用视频里可见的物体、不得是原指令的更易版；(d) gpt-5-mini 做拒绝式验证，指令与视频不吻合或分数与 rubric 不符就整组重生成。上面的例子会得到 place pepper in the shelf（3 分，辣椒确实被操作了）与 clean the pot on the stove（1 分）这类指令。</li><li><strong>时序截断</strong>。保持原指令不变，把成功视频剪到若干预定比例的终点（早/中/晚），生成一小串&quot;进度阶梯&quot;，同样过验证。</li><li><strong>rubric</strong>。1 = 末态无目标相关变化；2 = 有微小但不足的进展；3 = 进展明显但违反多条或一条核心要求；4 = 区域与意图正确、只差一条次要要求；5 = 全部满足。3 与 4 的分界写得非常细：主目标物体身份与主空间关系都对、只丢了辅助约束（例如没保持原来的垫布在下面）算 4，不算 3。</li><li><strong>切分与规模</strong>。按<strong>原始任务描述</strong>切分，train/val/test 的任务描述互不重叠，避免同任务泄漏。最终 54,135 例：train 45,072、val 6,232、test 2,831。</li><li><strong>训练</strong>。微调 Qwen3-VL 的 4B 与 8B 两档，冻结视觉主干，只训 fusion 与 LLM 层；3 epoch、cosine 衰减、warmup 比例 0.05、weight decay 0.05、梯度裁剪 1.0、梯度累积后有效 batch 32、学习率 4B 用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">6</span></span></span></span></span></span></span></span></span></span></span></span>、8B 用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">6</span></span></span></span></span></span></span></span></span></span></span></span>；按验证集 MAE 选 checkpoint。</li><li><strong>评测集</strong>。test split 逐条人工核验：标注员看视频、任务文本、给定分数、rubric 以及 gpt-5-mini 的验证理由，判断标签是否站得住，站不住就丢弃。剩下的 2,831 条即 <strong>RoboRewardBench</strong>，覆盖 14 类本体、内外视角混合。</li><li><strong>下游 RL</strong>。WidowX 250 六自由度机械臂，基座策略是在 BridgeData V2 上预训练、用目标图像条件化的 diffusion transformer policy；RL 算法是 DSRL-SAC，先用基座策略 rollout 20 次预热 replay buffer，再训 6000 步，每回合最多 70 步。两个 VLM 奖励模型都是 zero-shot prompt，不再微调。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>论文的形式化很轻，但每一步都对应一个可检验的设计决策。</p><p>RL 目标照例是最大化期望回报 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">π</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">:=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2449em;vertical-align:-0.3949em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">π</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size1">[</span></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">≥</span><span class="mord mtight">0</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3949em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7936em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size1">]</span></span></span></span></span></span>。本文把奖励限制为<strong>回合级</strong>（episodic）：一整条 rollout 拿一个数，而不是逐步打分。这是真机 RL 的常见做法，也直接决定了奖励模型的输入是完整视频而非单帧。</p><p>奖励取值域定为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">3</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">4</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">5</span><span class="mclose">}</span></span></span></span> 的离散进度分，评价指标是平均绝对误差</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">MAE</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">:=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">∣</span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose delimcenter" style="top:0em;">∣</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 为真值、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 为预测。选 MAE 而非准确率是有讲究的：进度分是<strong>有序</strong>变量，把 5 预测成 4 与预测成 1 的代价完全不同，而分类准确率对这两种错误一视同仁。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord"><span class="mord mathrm">MAE</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 的直观含义是平均误差不到一个进度档。</p><p>数据增广那一步可以写得更精确。设一条成功回合为三元组 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">e</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mclose">)</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span></span></span> 是视频、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 是指令、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span>。两种增广各生成一组新三元组：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1019em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord cjk_fallback">反事实：</span></span><span class="mspace"> </span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8519em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">t</span></span><span style="top:-3.5341em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">~</span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">~</span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord cjk_fallback">截断：</span></span><span class="mspace"> </span><span class="mopen">(</span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">~</span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">~</span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">~</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">3</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">4</span><span class="mclose">}</span><span class="mord">.</span></span></span></span></span></p><p>一个只动文本、一个只动视频，两者互补地覆盖了 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span></span></span></span> 联合空间的两条正交方向。作者把它称作 <strong>inverse-HER</strong>：HER 把失败重标为成功以扩充正例，这里方向相反。二者共享同一个数学前提——<strong>同一段轨迹在不同目标下有不同回报</strong>，因此可以在不采新数据的情况下扩展监督。</p><p>有一处推断值得标出（<strong>这是解读者的推断，不是论文的声明</strong>）：反事实重标注只改变语言，因此它教给模型的是&quot;视频与指令有多匹配&quot;这一维；时序截断只改变视频长度与末态，教的是&quot;进度走了多远&quot;这一维。真实的执行失败（抓空、滑落、位姿偏差）<strong>两维都不占</strong>——它语言匹配、时长正常，只是物理上没做成。§9 会用论文自己的消融数字检验这条推断。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：现成 VLM 能直接当机器人奖励模型吗？</strong> 在 RoboRewardBench 上评 22 个模型，指标为 group-wise MAE。答案是不能可靠地用。最强的通用模型是 GPT-5 mini（0.691），GPT-5 为 0.811，Gemini 3 Pro (Preview) 0.851，Gemini 2.5 Pro 0.902，最弱的 Qwen2.5-VL 3B 到 1.607。问题不止于总分，还有<strong>非均匀性</strong>：GPT-5 总榜第 3，但在 Austin VIOLA 上误差 0.283、在 Tokyo PR2 Tabletop 上却到 1.366；Gemini 3 Pro 在 Berkeley RPT 上 0.395，在 KAIST Nonprehensile 上 1.491。<strong>专门在机器人数据上训过的 Gemini Robotics-ER 1.5 总排名只有 11/22（0.906）</strong>，说明&quot;见过机器人数据&quot;并不自动等于&quot;会打分&quot;。</p><p><strong>问题二：专门训练能否超过更大的通用 VLM？</strong> RoboReward 8B 以 0.665 排第一，4B 以 0.845 排第四。同架构对比更干净：8B 相对 Qwen3-VL Instruct 8B 从 0.892 降到 0.665（改善 0.227），4B 相对 Qwen3-VL Instruct 4B 从 1.032 降到 0.845（改善 0.187）。结论有同架构对照支撑，不是靠挑基线挑出来的。作者也如实指出 8B 不是逐子集全胜：在 UTokyo xArm Bimanual 上误差 1.394，在 Stanford HYDRA 上 0.890 只排 8/22，而该子集最好的 Gemini 2.5 Pro 是 0.495。</p><p><strong>问题三：更好的奖励模型能否转化成更好的策略？</strong> WidowX 上两个未见任务，20 次试验取成功率。Pick-and-place monkey：基座策略 5%，人工奖励 75%，RoboReward 8B 50%，Gemini Robotics-ER 1.5 只有 10%。Open drawer：基座 10%，人工 90%，RoboReward 8B 80%，Gemini Robotics-ER 1.5 45%。两个任务上奖励模型的排序与它们在 RoboRewardBench 上的 MAE 排序一致，与仿真里 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.83</span></span></span></span> 的相关性互相印证。同时必须看到，pick-and-place 上 50% vs 75% 的差距仍然很大，作者没有回避这一点。</p><p><strong>问题四（消融）：两种增广各自贡献多少？</strong> 用 4B 模型做数据混合消融。只用 RoboArena + 原始 OXE 成功样本（不做任何负例增广）时，总榜 MAE 从 0.845 恶化到 1.450，<strong>但 RoboArena 子集上是 0.797，反而略优于完整配方的 0.806</strong>。去掉截断负例、保留反事实标注时，总榜 1.075、RoboArena 0.813。作者的解读是 RoboArena 的有机失败质量高但覆盖窄（单一平台），构造负例提供的是跨场景、跨本体的广度。</p><p>附录 B.3 提供了一组很有价值的定性证据：让 Gemini Robotics-ER 1.5 描述它打错分的视频。抓取失败、抽屉没开的那条，它描述成&quot;手指合拢扣住把手&quot;&quot;拖动了盒子&quot;，然后打 5/5；抽屉真被拉开的那条，它的描述停在&quot;看起来准备去抓&quot;，打 2/5；猴子玩偶悬在毛巾上方未放下的那条，它写成&quot;把玩偶放到布上&quot;，打 5/5。三例的共同结构是模型能正确描述静态场景，却<strong>把典型操作叙事补全成了它没看到的结果</strong>。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：(1) 先在 Robomimic 上确认离散进度奖励比学出来的二值成功奖励更利于 RL 收敛，且奖励模型离线准确率与下游 RL 成绩相关系数达 0.83。(2) 大规模真机语料成功偏重，作者用零机器人成本的 inverse-HER 式增广造负例：反事实重标注与时序截断，配严格 rubric 与 VLM 拒绝式验证。(3) 由此得到 54,135 例数据（45,072/6,232/2,831），测试集逐条人工核验成为 RoboRewardBench，覆盖 14 类本体。(4) 22 个 VLM 中无一全面胜出且跨子集波动极大；微调后的 RoboReward 8B 以 MAE 0.665 排第一，同架构相对 Qwen3-VL 8B 改善 0.227。(5) 8B 驱动 WidowX 真机 RL，两个任务分别从 5%/10% 提到 50%/80%，优于 Gemini Robotics-ER 1.5 的 10%/45%，但仍低于人工奖励的 75%/90%。</p><p><strong>3 句话版</strong>：把&quot;缺负例&quot;这个数据问题用两种零成本增广解决，把通用机器人奖励模型从设想变成可训练对象。22 模型基准显示现成 VLM 不可直接依赖，专训 8B 反而最准，且这个排序在真机 RL 上复现。但消融显示，在唯一一批<strong>有机失败</strong>数据（RoboArena）上，去掉全部增广的模型反而更好一点（0.797 vs 0.806）。</p><p><strong>1 句话版</strong>：用换指令和剪视频给成功语料造出 1–5 分的负例阶梯，训出能真正驱动真机 RL 的通用机器人奖励模型。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>由反事实重标注与时序截断构造出的负例，能够代表真实部署中会遇到的失败分布</strong>。</p><p>这条假设是整个方法的地基。增广并没有真正补上失败样本，它补上的是<strong>两类结构化的、与执行失败正交的负例</strong>：语言-视频不匹配，以及进度不完整。真实的机器人失败是手指滑开、物体被碰倒、插入偏了两毫米、位姿差了半个身位——这些视频与成功视频在语言匹配度上几乎没有差别，在时长上也可能完全正常。</p><p>论文自己的 Table 3 恰好给出了检验这条担忧的数字，而且方向不利于增广。RoboArena 是全套数据里<strong>唯一</strong>一批由人类评测员对真实策略 rollout 打分的有机成功/失败混合数据。在这个子集上：完整配方 0.806，去掉全部负例增广 0.797，去掉截断负例 0.813。三者落在同一水平，去掉全部增广甚至最好。也就是说，<strong>增广带来的 0.845 vs 1.450 的巨大总榜差距，几乎全部来自那些本身由增广生成的子集</strong>，而在有机失败上它没有提供可测量的收益。作者对此的解释是 RoboArena 覆盖窄（单平台），这个解释成立，但它同时意味着&quot;增广负例能迁移到有机失败&quot;在论文里<strong>没有被正面证据支持</strong>。</p><p>反过来说，论文也给出了这条假设不至于致命的证据：真机 RL 上 8B 确实把成功率从 5%/10% 抬到 50%/80%，说明它对真实 rollout 的成败判断有实质信息量。但残余差距（pick-and-place 上 50% vs 人工的 75%）很可能正落在两类构造负例覆盖不到的失败模式上，而附录 B.3 里 Gemini 的三个失败案例（把没抓住写成抓住、把悬空写成放下）正是这类模式的样本。同类现象在<a href="/notes/papers/2412.02617">基于 AI 反馈的动作数据集</a>里也被独立观察到：VLM 裁判的接受率远高于人类。</p><p><strong>判别性证据仍然缺失</strong>：需要把 RoboRewardBench 按&quot;构造负例 / 有机失败&quot;拆开分别报 MAE，并在有机失败子集上对照一个只看视频时长的退化基线。论文报的是按数据集来源的拆分，不是按负例类型的拆分。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要真机，且数据集、模型权重与评测套件已开源：</p><ul><li><strong>数据</strong>：下载 RoboRewardBench，按来源切成两堆——RoboArena 那 1000 条（人类打分的有机成败混合）与其余 OXE 派生子集（由增广生成）。</li><li><strong>实现</strong>：不训练模型。跑四个打分器：开源的 RoboReward 8B、未微调的 Qwen3-VL 8B，以及两个退化基线——只用视频帧数线性映射到 1–5 的常数打分器，以及只用末帧图像与指令的 CLIP 相似度分档的无训练打分器。</li><li><strong>测量</strong>：两堆数据上分别的 MAE 与 reliability diagram；再算一个论文没报的量——预测分与视频帧数的 Spearman 相关。</li><li><strong>判据</strong>：若 RoboReward 8B 在增广子集上远优于两个退化基线、而在 RoboArena 上与它们的差距明显收窄，则 §9 的担忧成立。若预测分与帧数的相关性超过 0.5，说明时序截断引入的长度捷径确实被学进去了。这组实验只需推理算力，却直接判定该路线能否规模化。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的替代解释是：<strong>本文训出的其实是一个&quot;视频-指令对齐 + 进度长度&quot;的复合打分器，它在真机 RL 里之所以有效，是因为在这两个任务上&quot;指令对得上且走完了流程&quot;与&quot;任务做成了&quot;高度共线</strong>。</p><p>最锐利的检验是<strong>打破共线性</strong>：构造一批&quot;指令语义完全正确执行、时长完整、但物理上失败&quot;的 rollout（机器人按正确顺序伸向正确物体、做出完整的抓-移-放动作，但抓空或中途滑落）。附录 B.3 里 Gemini 打错的三例正是这个分布的样本，而论文并未报告 RoboReward 8B 在同样这三例上的打分。若它在这批数据上的 MAE 显著劣于 0.665，替代解释成立。</p><p>第二条攻击针对时序截断。截断产生的负例在<strong>视频帧数</strong>上与正例系统性不同，而帧数是极易被学到的捷径。廉价的负控制是把正例也随机截断到与负例相同的长度分布后再评测。论文的消融表明去掉截断负例会让总榜从 0.845 恶化到 1.075，作者把这解释为&quot;覆盖更多失败模式&quot;；同一数字也与&quot;截断负例给了模型一个好用的长度捷径、而该捷径在同样由截断构造的测试子集上继续奏效&quot;完全兼容。两种解释论文没有分离。</p><p>第三条针对真机 RL 的样本量。两个任务、每个 20 次试验，未报告重复种子或置信区间。按 Wilson 区间估算，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">20</span></span></span></span> 下 50% 的 95% 区间约为 30%–70%（解读者计算，非论文数字）。结论的方向——RoboReward 8B 优于 Gemini Robotics-ER 1.5、劣于人工——大概率成立，但&quot;缩小了多少差距&quot;这个定量表述不宜当作精确值引用。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：本文把奖励建模定义为<strong>回合级判别</strong>——给一整段视频，输出一个 1–5 的末态进度分。作者自己在 Discussion 里把&quot;扩展到长时程多阶段任务、其中 credit assignment 与进度估计更难&quot;列为未来工作。但单把同一套标注扩展到更长的任务解决不了问题：回合末的单个数字在长时程上信用分配极差，而时序截断造出的中间样本表达的是&quot;还没做完&quot;，不是&quot;做不成了&quot;。</p><p><strong>新的 framing</strong>：把奖励模型重新定义为<strong>可恢复性预测器</strong>——预测的不是&quot;这段视频做到几分&quot;，而是&quot;从当前这一帧的状态出发，任务最终被完成的概率是多少&quot;。这个量沿轨迹连续，天然给出稠密信号；更重要的是它把&quot;暂时偏离但能救回来&quot;与&quot;已进入不可恢复区&quot;区分开，而这恰恰是回合级进度分与截断负例都无法表达的维度。</p><p>标签从哪来是关键，而本文的数据源已经把它准备好了：RoboArena 产生的是<strong>真实策略 rollout</strong>，每条都有人类给的最终进度分。对任意一帧打上&quot;该 rollout 最终得几分&quot;的标签，就得到了可恢复性的蒙特卡罗估计，不需要任何新标注，也顺带把 §9 指出的&quot;增广负例覆盖不到有机失败&quot;这个缺口从数据侧补上。</p><p><strong>可借鉴的相邻工具</strong>：安全 RL 的可达性/生存性值函数给出了这类量的无衰减 Bellman 备份形式（学&quot;能否到达目标集&quot;而非折扣回报，因此绕路不受惩罚）；conformal prediction 可以把预测校准成有覆盖保证的区间，从而给出一个原则性的&quot;该停下来求助&quot;的阈值——这正是安全部署最需要而当前奖励模型完全不提供的东西。</p><p><strong>第一个实验</strong>：在同一批 RoboArena rollout 上训练两个头——本文式的回合级进度分头，以及帧级可恢复性预测头。度量三件事：(a) 回合级 MAE（预期两者相当）；(b) <strong>首次预警时间</strong>，即在最终低分的 rollout 中，模型第一次给出低分的时刻距离失败发生还有多久；(c) 在 WidowX 的同两个任务上用两者分别做 DSRL，比较达到同一成功率所需的真机步数。若 (b) 上可恢复性头显著提前、(c) 上样本效率更高，就说明&quot;奖励模型 = 回合级判别器&quot;这一默认设定在长时程上是错的选择，而这一改动只需要换标签定义、不需要新数据。</p>',65)])])}const d=a(e,[["render",l]]);export{h as __pageData,d as default};
